#include <iostream>
#include <fstream>
#include <iomanip>
#include <cstring>
#include <vector>
#include <queue>
#include <complex>
#include <chrono>
#include <random>
#include <cassert>
#include <climits>
#include <cmath>

using namespace std;

typedef long long lint;
typedef long double ldouble;
typedef pair<int, int> pi;
typedef pair<lint, lint> pli;
typedef pair<ldouble, ldouble> pd;

constexpr char NEWLINE = '\n';
constexpr lint INF_dist = 0x3f3f3f3f;
constexpr lint INF64_dist = 0x3f3f3f3f3f3f3f3f;
constexpr lint MOD_val = 1000000007LL;
constexpr ldouble EPSILON_val = 1e-10L;

mt19937_64 rng_standalone(chrono::steady_clock::now().time_since_epoch().count());

constexpr int time_steps = 99;
constexpr int cost_levels = 15;

struct MinCostMaxFlow {
    static const int MAX_VERTICES = 50 * time_steps + 2;
    static const int MAX_EDGES = 2 * MAX_VERTICES * cost_levels + MAX_VERTICES + 7;

    int prev_node[MAX_VERTICES];
    int adjacency_head[MAX_VERTICES];
    int edge_next[MAX_EDGES * 2];
    int edge_dest[MAX_EDGES * 2];
    int num_edges;

    lint edge_flow[MAX_EDGES * 2];
    lint edge_capacity[MAX_EDGES * 2];
    lint edge_cost[MAX_EDGES * 2];

    bool visited_flag[MAX_VERTICES];
    int work_queue[MAX_VERTICES];
    int queue_index[MAX_VERTICES];

    lint shortest_dist[MAX_VERTICES];
    lint vertex_potential[MAX_VERTICES];

    void clear() {
        num_edges = 0;
        memset(adjacency_head, -1, sizeof(adjacency_head));
        memset(edge_flow, 0, sizeof(edge_flow));
    }

    void add_arc(int u, int v, lint cap, lint price = 0) {
        int idx = num_edges++;
        edge_next[idx] = adjacency_head[edge_dest[idx] = u];
        adjacency_head[edge_dest[idx]] = idx;
        edge_capacity[idx] = cap;
        edge_cost[idx] = price;

        idx = num_edges++;
        edge_next[idx] = adjacency_head[edge_dest[idx] = v];
        adjacency_head[edge_dest[idx]] = idx;
        edge_capacity[idx] = 0;
        edge_cost[idx] = -price;
    }

    void build_potentials(int n) {
        memset(vertex_potential, 0, sizeof(vertex_potential));
        for (int k = 1; k < n; ++k) {
            for (int e = 0; e < num_edges; ++e) {
                if (edge_capacity[e]) {
                    vertex_potential[edge_dest[e^1]] = min(vertex_potential[edge_dest[e^1]], vertex_potential[edge_dest[e]] + edge_cost[e]);
                }
            }
        }
    }

    lint improve_flow(int src, int dest, lint& total_expense, int n) {
        memset(visited_flag, 0, sizeof(visited_flag));
        fill(shortest_dist, shortest_dist + n, INF_dist);
        shortest_dist[src] = 0;
        memset(queue_index, -1, sizeof(queue_index));

        int head = 0, tail = 0;
        queue_index[work_queue[tail++] = src] = 0;

        while (head < tail) {
            int u = work_queue[head++];
            queue_index[u] = -1;

            for (int e = adjacency_head[u]; e != -1; e = edge_next[e]) {
                int v = edge_dest[e^1];
                if (edge_flow[e] < edge_capacity[e] && shortest_dist[v] > shortest_dist[u] + vertex_potential[u] - vertex_potential[v] + edge_cost[e]) {
                    shortest_dist[v] = shortest_dist[u] + vertex_potential[u] - vertex_potential[v] + edge_cost[e];
                    prev_node[v] = e;

                    if (queue_index[v] == -1) {
                        queue_index[work_queue[tail] = v] = tail;
                        ++tail;
                    }

                    for (int i = queue_index[v], j = (i - 1) / 2; i > 0 && shortest_dist[work_queue[i]] < shortest_dist[work_queue[j]]; i = j, j = (i - 1) / 2) {
                        swap(work_queue[i], work_queue[j]);
                        swap(queue_index[work_queue[i]], queue_index[work_queue[j]]);
                    }
                }
            }
        }

        if (shortest_dist[dest] >= INF_dist) return 0;

        lint aug = INF64_dist;
        for (int e, node = dest; node != src; node = edge_dest[e]) {
            e = prev_node[node];
            aug = min(aug, edge_capacity[e] - edge_flow[e]);
        }

        for (int e, node = dest; node != src; node = edge_dest[e]) {
            e = prev_node[node];
            edge_flow[e] += aug;
            edge_flow[e^1] -= aug;
            total_expense += aug * edge_cost[e];
        }

        for (int i = 0; i < n; ++i) {
            vertex_potential[i] = min((lint)INF_dist, shortest_dist[i] + vertex_potential[i]);
        }

        return aug;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int SOURCE_VERTEX = 0;
    const int SINK_VERTEX = n * time_steps + 1;
    MinCostMaxFlow flow_instance;
    flow_instance.clear();

    for (int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        flow_instance.add_arc(SOURCE_VERTEX, a, 1, 0);
    }

    for (int t = 0; t < time_steps; ++t) {
        flow_instance.add_arc(1 + t * n, SINK_VERTEX, INF_dist, 0);
        if (t > 0) {
            for (int i = 1; i <= n; ++i) {
                flow_instance.add_arc(i + (t - 1) * n, i + t * n, INF_dist, c);
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < cost_levels; ++j) {
            int step_cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < time_steps; ++t) {
                flow_instance.add_arc(a + (t - 1) * n, b + t * n, 1, step_cost * d + c);
                flow_instance.add_arc(b + (t - 1) * n, a + t * n, 1, step_cost * d + c);
            }
        }
    }

    flow_instance.build_potentials(MinCostMaxFlow::MAX_VERTICES);

    lint total_cost = 0;
    lint total_flow = 0;

    while (lint delta = flow_instance.improve_flow(SOURCE_VERTEX, SINK_VERTEX, total_cost, MinCostMaxFlow::MAX_VERTICES)) {
        total_flow += delta;
    }

    assert(total_flow == k);
    cout << total_cost << NEWLINE;

    return 0;
}
